/* sb_fill.js — the "Fill the table" and "Show the work" buttons of the books.
 * A table whose cells the student has to fill in gets a button above it; pressing it writes the correct answer into every empty cell (cells the
 * printed row is missing are added), pressing it again empties them. A project or activity box gets "Show the work": a panel under the box with
 * what the project asks for done out (a model, a table, a list, a report outline). Both come from js/fills_data.js (SB_FILLS, generated by
 * tools/fills/build_fills.js from tools/fills/src/*.json); the reader (js/math6_reader.js) only draws a button where a fill exists, found by a
 * hash of the book title and the text of the table / box. Works the same in the app's page. */
(function () {
  'use strict';
  const CSS = `
  .sb-fill-bar{display:flex;justify-content:flex-end;margin:0 0 .3rem}
  .sb-fill-btn{display:inline-flex;align-items:center;gap:.35em;min-height:1.9em;margin-inline-start:.6em;padding:.15em .85em;border:none;border-radius:999px;background:#6d28d9;color:#fff;font:700 .8rem/1.2 system-ui,sans-serif;letter-spacing:.01em;cursor:pointer;box-shadow:0 1px 3px rgba(0,0,0,.22);vertical-align:middle}
  .sb-fill-btn::before{content:"✎";font-size:1.05em}
  .sb-fill-btn:hover,.sb-fill-btn:focus-visible{background:#5b21b6;outline:2px solid #c4b5fd;outline-offset:1px}
  .sb-fill-btn[aria-pressed="true"],.sb-fill-btn[aria-expanded="true"]{background:#3b0764}
  .sb-fill-btn[aria-pressed="true"]::before,.sb-fill-btn[aria-expanded="true"]::before{content:"✕"}
  .m6-table td.sb-filled{background:#dcfce7;color:#14532d;font-weight:500}
  .m6-table td.sb-filled.sb-short{font-weight:700}
  .m6-table td.sb-filled svg{max-width:100%;height:auto;vertical-align:middle}
  .m6-table td.sb-filled .sb-sm{display:block;font-weight:500;font-size:.82em;color:#166534}
  .sb-work{margin:.7rem 0 .2rem;padding:.2rem .7rem .5rem;border-inline-start:4px solid #16a34a;background:#f0fdf4;border-radius:8px}
  .sb-work[hidden]{display:none}
  .sb-work-t{margin:.35rem 0;font:800 .78rem/1.2 system-ui,sans-serif;letter-spacing:.04em;text-transform:uppercase;color:#166534}
  .sb-work .m6-table table{width:100%}
  .sb-work .m6-table td,.sb-work .m6-table th{text-align:start;overflow-wrap:normal;word-break:normal;hyphens:none}
  .sb-work .m6-fig{display:inline-block;margin:.4rem .6rem;vertical-align:top}
  .sb-work .m6-fig svg{width:auto;max-width:min(100%,230px);height:auto}
  .sb-work .m6-fig figcaption{max-width:230px;margin-inline:auto}`;
  function addCss() { if (document.getElementById('sb-fill-css')) return; const s = document.createElement('style'); s.id = 'sb-fill-css'; s.textContent = CSS; document.head.appendChild(s); }
  addCss();
  const R = () => window.MATH6_READER;
  const fillOf = el => { const w = el.closest('[data-fkey]'); return w && window.SB_FILLS && window.SB_FILLS[w.dataset.fkey]; };
  // a value starting with "<svg" is a drawing; anything else is text (with the book's $math$ and word hovering switched off)
  const paint = (td, v) => { if (/^\s*<svg/.test(v)) td.innerHTML = v; else td.innerHTML = R().inline(String(v), false); };

  function fillTable(btn) {
    addCss();
    const wrap = btn.closest('.m6-table'), fl = fillOf(btn);
    if (!wrap || !fl || !fl.rows) return;
    const on = btn.getAttribute('aria-pressed') !== 'true';
    const trs = wrap.querySelectorAll('tbody tr');
    if (on) {
      fl.rows.forEach((row, i) => {
        const tr = trs[i]; if (!tr) return;
        row.forEach((v, j) => {
          let td = tr.cells[j], added = false;
          if (!td) { td = document.createElement('td'); tr.appendChild(td); added = true; }
          if (!added && td.textContent.trim()) return;
          if (!added && td.children.length) return;
          paint(td, v);
          td.classList.add('sb-filled'); if (String(v).length <= 14) td.classList.add('sb-short'); if (added) td.dataset.sbAdded = '1';
        });
      });
    } else {
      wrap.querySelectorAll('td.sb-filled').forEach(td => { if (td.dataset.sbAdded) td.remove(); else { td.textContent = ''; td.classList.remove('sb-filled', 'sb-short'); } });
    }
    btn.setAttribute('aria-pressed', String(on));
    btn.textContent = on ? 'Empty the table' : 'Fill the table';
  }

  function showWork(btn) {
    addCss();
    const box = btn.closest('.m6-box'), fl = fillOf(btn);
    if (!box || !fl || !fl.blocks) return;
    let panel = box.querySelector(':scope > .sb-work');
    if (!panel) {
      panel = document.createElement('div'); panel.className = 'sb-work'; panel.hidden = true;
      panel.innerHTML = `<div class="sb-work-t">The work for this project</div>${R().blocks(fl.blocks, {noPages: true})}`;
      box.appendChild(panel);
    }
    const open = panel.hidden;
    panel.hidden = !open;
    btn.setAttribute('aria-expanded', String(open));
    btn.textContent = open ? 'Hide the work' : 'Show the work';
    if (open && panel.scrollIntoView) { try { panel.scrollIntoView({block: 'nearest', behavior: 'smooth'}); } catch (e) { /* old webview */ } }
  }
  window.SBFill = {table: fillTable, work: showWork};
})();
